# ---------------------------------------------------------------------------
# Virtualization primitives. No new runtime dependency.
# ---------------------------------------------------------------------------
write(
    "apps/web/src/files/virtualization.ts",
    '''import { useEffect, useMemo, useState } from "react";\n\nexport const LIST_ROW_HEIGHT = 40;\nexport const MILLER_ROW_HEIGHT = 32;\nexport const GRID_TILE_HEIGHT = 108;\nexport const GRID_GAP = 8;\nexport const GRID_ROW_HEIGHT = GRID_TILE_HEIGHT + GRID_GAP;\nexport const GRID_MIN_TILE_WIDTH = 96;\n\nexport interface VirtualRange {\n  start: number;\n  end: number;\n  paddingBefore: number;\n  paddingAfter: number;\n}\n\nexport function computeVirtualRange(\n  count: number,\n  itemSize: number,\n  scrollOffset: number,\n  viewportSize: number,\n  overscan = 8,\n): VirtualRange {\n  if (count <= 0 || itemSize <= 0) {\n    return { start: 0, end: 0, paddingBefore: 0, paddingAfter: 0 };\n  }\n  const safeOffset = Math.max(0, scrollOffset);\n  const safeViewport = Math.max(itemSize, viewportSize);\n  const visibleStart = Math.floor(safeOffset / itemSize);\n  const visibleEnd = Math.ceil((safeOffset + safeViewport) / itemSize);\n  const start = Math.max(0, visibleStart - overscan);\n  const end = Math.min(count, visibleEnd + overscan);\n  return {\n    start,\n    end,\n    paddingBefore: start * itemSize,\n    paddingAfter: Math.max(0, (count - end) * itemSize),\n  };\n}\n\nexport function useVirtualWindow(\n  scrollElement: HTMLElement | null,\n  count: number,\n  itemSize: number,\n  overscan = 8,\n): VirtualRange {\n  const [viewport, setViewport] = useState({ scrollOffset: 0, size: 720 });\n\n  useEffect(() => {\n    if (!scrollElement) return;\n    const update = () => {\n      setViewport({\n        scrollOffset: scrollElement.scrollTop,\n        size: scrollElement.clientHeight || 720,\n      });\n    };\n    update();\n    scrollElement.addEventListener("scroll", update, { passive: true });\n    const resize = new ResizeObserver(update);\n    resize.observe(scrollElement);\n    return () => {\n      scrollElement.removeEventListener("scroll", update);\n      resize.disconnect();\n    };\n  }, [scrollElement]);\n\n  return useMemo(\n    () => computeVirtualRange(count, itemSize, viewport.scrollOffset, viewport.size, overscan),\n    [count, itemSize, overscan, viewport.scrollOffset, viewport.size],\n  );\n}\n\nexport function useElementWidth(element: HTMLElement | null, fallback = 800): number {\n  const [width, setWidth] = useState(fallback);\n  useEffect(() => {\n    if (!element) return;\n    const update = () => setWidth(element.clientWidth || fallback);\n    update();\n    const resize = new ResizeObserver(update);\n    resize.observe(element);\n    return () => resize.disconnect();\n  }, [element, fallback]);\n  return width;\n}\n''',
)

write(
    "apps/web/src/files/virtualization.test.ts",
    '''import { describe, expect, it } from "vitest";\nimport { computeVirtualRange } from "./virtualization";\n\ndescribe("computeVirtualRange", () => {\n  it("keeps a large directory DOM window bounded", () => {\n    const range = computeVirtualRange(50_000, 40, 800_000, 720, 8);\n    expect(range.end - range.start).toBeLessThanOrEqual(35);\n    expect(range.start).toBeGreaterThan(0);\n    expect(range.paddingBefore).toBeGreaterThan(0);\n    expect(range.paddingAfter).toBeGreaterThan(0);\n  });\n\n  it("clamps the first and last windows", () => {\n    expect(computeVirtualRange(10, 40, 0, 400, 8)).toEqual({\n      start: 0, end: 10, paddingBefore: 0, paddingAfter: 0,\n    });\n    const tail = computeVirtualRange(1_000, 40, 40_000, 400, 4);\n    expect(tail.end).toBe(1_000);\n    expect(tail.paddingAfter).toBe(0);\n  });\n});\n''',
)

write(
    "apps/web/src/files/useMarqueeSelection.tsx",
    '''import { useCallback, useRef, useState, type CSSProperties, type PointerEvent } from "react";\n\ntype Point = { x: number; y: number; pointerId: number };\ntype Rect = { left: number; top: number; width: number; height: number };\n\nfunction rectangle(start: Point, x: number, y: number): Rect {\n  return {\n    left: Math.min(start.x, x),\n    top: Math.min(start.y, y),\n    width: Math.abs(x - start.x),\n    height: Math.abs(y - start.y),\n  };\n}\n\nfunction intersects(rect: Rect, element: Element): boolean {\n  const item = element.getBoundingClientRect();\n  return !(\n    item.right < rect.left\n    || item.left > rect.left + rect.width\n    || item.bottom < rect.top\n    || item.top > rect.top + rect.height\n  );\n}\n\nexport function useMarqueeSelection({\n  itemSelector,\n  blockedStartSelector,\n  onSelect,\n}: {\n  itemSelector: string;\n  blockedStartSelector: string;\n  onSelect: (paths: string[], additive: boolean) => void;\n}) {\n  const startRef = useRef<Point | null>(null);\n  const [rect, setRect] = useState<Rect | null>(null);\n\n  const onPointerDownCapture = useCallback((event: PointerEvent<HTMLElement>) => {\n    if (event.button !== 0) return;\n    const target = event.target as Element | null;\n    if (target?.closest(blockedStartSelector)) return;\n    startRef.current = { x: event.clientX, y: event.clientY, pointerId: event.pointerId };\n    event.currentTarget.setPointerCapture(event.pointerId);\n  }, [blockedStartSelector]);\n\n  const onPointerMoveCapture = useCallback((event: PointerEvent<HTMLElement>) => {\n    const start = startRef.current;\n    if (!start || start.pointerId !== event.pointerId) return;\n    const next = rectangle(start, event.clientX, event.clientY);\n    if (next.width >= 2 || next.height >= 2) {\n      event.preventDefault();\n      setRect(next);\n    }\n  }, []);\n\n  const finish = useCallback((event: PointerEvent<HTMLElement>) => {\n    const start = startRef.current;\n    if (!start || start.pointerId !== event.pointerId) return;\n    const finalRect = rectangle(start, event.clientX, event.clientY);\n    startRef.current = null;\n    setRect(null);\n    if (event.currentTarget.hasPointerCapture(event.pointerId)) {\n      event.currentTarget.releasePointerCapture(event.pointerId);\n    }\n    if (finalRect.width < 4 && finalRect.height < 4) return;\n    const paths = Array.from(event.currentTarget.querySelectorAll(itemSelector))\n      .filter((element) => intersects(finalRect, element))\n      .map((element) => element.getAttribute("data-path"))\n      .filter((path): path is string => Boolean(path));\n    onSelect(paths, event.shiftKey || event.metaKey || event.ctrlKey);\n  }, [itemSelector, onSelect]);\n\n  const onPointerCancelCapture = useCallback((event: PointerEvent<HTMLElement>) => {\n    if (startRef.current?.pointerId !== event.pointerId) return;\n    startRef.current = null;\n    setRect(null);\n  }, []);\n\n  const marqueeStyle: CSSProperties | null = rect\n    ? { left: rect.left, top: rect.top, width: rect.width, height: rect.height }\n    : null;\n\n  return {\n    marqueeStyle,\n    onPointerDownCapture,\n    onPointerMoveCapture,\n    onPointerUpCapture: finish,\n    onPointerCancelCapture,\n  };\n}\n''',
)

