write(
    "apps/web/src/files/FileGrid.tsx",
    '''import { useCallback, useMemo, useState } from "react";\nimport { File, FileArchive, FileCode, FileImage, FileText, Folder, Link2 } from "lucide-react";\nimport type { FileEntry } from "../types";\nimport { EntryActionButtons, InlineRenameInput, type PaneActions } from "./entry-widgets";\nimport { useFilesManager } from "./FilesManagerContext";\nimport { useMarqueeSelection } from "./useMarqueeSelection";\nimport type { UseFilePaneResult } from "./useFilePane";\nimport {\n  GRID_GAP,\n  GRID_MIN_TILE_WIDTH,\n  GRID_ROW_HEIGHT,\n  useElementWidth,\n  useVirtualWindow,\n} from "./virtualization";\n\ntype FileCategory = "code" | "archive" | "image" | "text" | "generic";\n\nfunction categorize(name: string): FileCategory {\n  const ext = name.split(".").pop()?.toLowerCase() ?? "";\n  if (["py", "js", "ts", "tsx", "jsx", "sh", "bash", "c", "cpp", "h", "java", "go", "rs", "rb", "sql", "json", "yaml", "yml", "toml", "xml", "html", "css"].includes(ext)) return "code";\n  if (["tar", "gz", "tgz", "zip", "bz2", "xz", "7z", "rar"].includes(ext)) return "archive";\n  if (["png", "jpg", "jpeg", "gif", "svg", "webp", "bmp", "ico"].includes(ext)) return "image";\n  if (["txt", "md", "log", "csv", "rst", "tex"].includes(ext)) return "text";\n  return "generic";\n}\n\nfunction TileIcon({ entry, size = 30 }: { entry: FileEntry; size?: number }) {\n  if (entry.kind === "directory") return <Folder size={size} aria-hidden="true" className="tile-icon icon-folder" />;\n  if (entry.kind === "symlink") return <Link2 size={size} aria-hidden="true" className="tile-icon icon-link" />;\n  switch (categorize(entry.name)) {\n    case "code": return <FileCode size={size} aria-hidden="true" className="tile-icon icon-code" />;\n    case "archive": return <FileArchive size={size} aria-hidden="true" className="tile-icon icon-archive" />;\n    case "image": return <FileImage size={size} aria-hidden="true" className="tile-icon icon-image" />;\n    case "text": return <FileText size={size} aria-hidden="true" className="tile-icon icon-text" />;\n    default: return <File size={size} aria-hidden="true" className="tile-icon icon-file" />;\n  }\n}\n\nexport { categorize, TileIcon };\n\nexport function FileGrid({\n  pane,\n  actions,\n  dropTarget,\n}: {\n  pane: UseFilePaneResult;\n  actions: PaneActions;\n  dropTarget: string | null;\n}) {\n  const manager = useFilesManager();\n  const [container, setContainer] = useState<HTMLDivElement | null>(null);\n  const width = useElementWidth(container);\n  const columns = Math.max(1, Math.floor((width + GRID_GAP) / (GRID_MIN_TILE_WIDTH + GRID_GAP)));\n  const rowCount = Math.ceil(pane.entries.length / columns);\n  const scrollElement = container?.parentElement ?? null;\n  const range = useVirtualWindow(scrollElement, rowCount, GRID_ROW_HEIGHT, 4);\n  const startIndex = range.start * columns;\n  const endIndex = Math.min(pane.entries.length, range.end * columns);\n  const entries = pane.entries.slice(startIndex, endIndex);\n  const selectedSet = useMemo(() => new Set(pane.selected), [pane.selected]);\n\n  const openEntry = useCallback((entry: FileEntry) => {\n    if (entry.kind === "directory") pane.navigateTo(entry.path);\n  }, [pane]);\n\n  const handleMarquee = useCallback((paths: string[], additive: boolean) => {\n    manager.setActivePane(pane.paneId);\n    pane.setSelection(additive\n      ? Array.from(new Set([...pane.selected, ...paths]))\n      : paths);\n  }, [manager, pane]);\n  const marquee = useMarqueeSelection({\n    itemSelector: ".file-tile[data-path]",\n    blockedStartSelector: ".file-tile",\n    onSelect: handleMarquee,\n  });\n\n  return (\n    <div\n      className="filegrid virtual-filegrid"\n      ref={setContainer}\n      onPointerDownCapture={marquee.onPointerDownCapture}\n      onPointerMoveCapture={marquee.onPointerMoveCapture}\n      onPointerUpCapture={marquee.onPointerUpCapture}\n      onPointerCancelCapture={marquee.onPointerCancelCapture}\n    >\n      <div\n        className="filegrid-tiles virtual-filegrid-tiles"\n        style={{ paddingTop: range.paddingBefore, paddingBottom: range.paddingAfter }}\n        aria-setsize={pane.entries.length}\n      >\n        {entries.map((entry, localIndex) => {\n          const activate = (e: React.MouseEvent | React.KeyboardEvent) => {\n            manager.setActivePane(pane.paneId);\n            if (e.shiftKey || e.metaKey || e.ctrlKey) pane.toggleSelect(entry.path);\n            else if (entry.kind === "directory") openEntry(entry);\n            else pane.setSelection([entry.path]);\n          };\n          return (\n            <div\n              key={entry.path}\n              role="button"\n              tabIndex={0}\n              draggable\n              onDragStart={(e) => actions.onDragStartEntry(entry, e)}\n              onDragEnd={actions.onDragEndEntry}\n              className={`file-tile${selectedSet.has(entry.path) ? " selected" : ""}${\n                dropTarget === entry.path ? " drop-target" : ""\n              }`}\n              data-path={entry.path}\n              data-kind={entry.kind}\n              data-virtual-index={startIndex + localIndex}\n              title={entry.path}\n              onClick={activate}\n              onKeyDown={(e) => {\n                if (e.key === "Enter" || e.key === " ") {\n                  e.preventDefault();\n                  activate(e);\n                }\n              }}\n              onDoubleClick={() => openEntry(entry)}\n              onContextMenu={(e) => {\n                e.preventDefault();\n                e.stopPropagation();\n                if (!selectedSet.has(entry.path)) pane.setSelection([entry.path]);\n                actions.onOpenContext(entry, e.clientX, e.clientY);\n              }}\n            >\n              <TileIcon entry={entry} />\n              {pane.renamingPath === entry.path ? (\n                <InlineRenameInput\n                  initialName={entry.name}\n                  busy={pane.busy}\n                  onCommit={(name) => void pane.renameEntry(entry.path, name)}\n                  onCancel={() => pane.setRenamingPath(null)}\n                />\n              ) : (\n                <span className="tile-name">{entry.name}</span>\n              )}\n              <EntryActionButtons entry={entry} pane={pane} actions={actions} />\n            </div>\n          );\n        })}\n      </div>\n      {marquee.marqueeStyle ? <div className="file-marquee" style={marquee.marqueeStyle} /> : null}\n    </div>\n  );\n}\n''',
)

# ---------------------------------------------------------------------------
# Miller columns: per-column row windowing and path-based marquee.
# ---------------------------------------------------------------------------
write(
    "apps/web/src/files/MillerColumns.tsx",
    '''import { useInfiniteQuery } from "@tanstack/react-query";\nimport { useCallback, useEffect, useMemo, useState } from "react";\nimport { ChevronRight } from "lucide-react";\nimport { api } from "../api";\nimport type { FileEntry } from "../types";\nimport { EntryActionButtons, InlineRenameInput, type PaneActions } from "./entry-widgets";\nimport { useFilesManager, type FilesManager } from "./FilesManagerContext";\nimport { TileIcon } from "./FileGrid";\nimport { columnDirsFor } from "./selection";\nimport { useMarqueeSelection } from "./useMarqueeSelection";\nimport type { UseFilePaneResult } from "./useFilePane";\nimport { MILLER_ROW_HEIGHT, useVirtualWindow } from "./virtualization";\n\nfunction MillerColumn({\n  user, dir, nextDir, isLast, pane, actions, manager, dropTarget,\n}: {\n  user: string;\n  dir: string;\n  nextDir: string | null;\n  isLast: boolean;\n  pane: UseFilePaneResult;\n  actions: PaneActions;\n  manager: FilesManager;\n  dropTarget: string | null;\n}) {\n  const [body, setBody] = useState<HTMLDivElement | null>(null);\n  const listing = useInfiniteQuery({\n    queryKey: ["files-list", user, dir],\n    queryFn: ({ signal, pageParam }) => api.fileList(user, dir, { limit: 500, cursor: pageParam }, signal),\n    initialPageParam: null as string | null,\n    getNextPageParam: (lastPage) => lastPage.page.next_cursor ?? undefined,\n    retry: false,\n  });\n  const entries = useMemo(\n    () => listing.data?.pages.flatMap((page) => page.entries) ?? [],\n    [listing.data],\n  );\n  const selectedSet = useMemo(() => new Set(pane.selected), [pane.selected]);\n  const focusPath = nextDir ?? (isLast ? pane.selected[0] ?? null : null);\n  const focusIndex = focusPath ? entries.findIndex((entry) => entry.path === focusPath) : -1;\n\n  useEffect(() => {\n    if (!body || focusIndex < 0) return;\n    const top = focusIndex * MILLER_ROW_HEIGHT;\n    const bottom = top + MILLER_ROW_HEIGHT;\n    if (top < body.scrollTop) body.scrollTop = top;\n    else if (bottom > body.scrollTop + body.clientHeight) {\n      body.scrollTop = bottom - body.clientHeight;\n    }\n  }, [body, focusIndex]);\n\n  const range = useVirtualWindow(body, entries.length, MILLER_ROW_HEIGHT, 6);\n  const visibleEntries = entries.slice(range.start, range.end);\n  const label = dir === "/" ? "/" : (dir.split("/").filter(Boolean).pop() ?? dir);\n\n  return (\n    <div\n      className="miller-column"\n      data-miller-dir={dir}\n      data-last-column={isLast ? "true" : undefined}\n    >\n      <div className="miller-column-header" title={dir}>{label}</div>\n      <div className="miller-column-body" ref={setBody}>\n        {listing.isPending && <div className="miller-empty">加载中…</div>}\n        {listing.isError && <div className="miller-empty miller-error">加载失败</div>}\n        {!listing.isPending && !listing.isError && entries.length === 0 && (\n          <div className="miller-empty">空目录</div>\n        )}\n        {range.paddingBefore > 0 ? (\n          <div className="virtual-block-spacer" style={{ height: range.paddingBefore }} aria-hidden="true" />\n        ) : null}\n        {visibleEntries.map((entry: FileEntry, localIndex) => {\n          const isActive = nextDir === entry.path;\n          const isSelected = isLast && selectedSet.has(entry.path);\n          const renaming = pane.renamingPath === entry.path;\n          return (\n            <div\n              key={entry.path}\n              className={`miller-row${isActive ? " active" : ""}${isSelected ? " selected" : ""}${\n                dropTarget === entry.path ? " drop-target" : ""\n              }`}\n              data-path={entry.path}\n              data-kind={entry.kind}\n              data-virtual-index={range.start + localIndex}\n              title={entry.path}\n              draggable\n              onDragStart={(e) => actions.onDragStartEntry(entry, e)}\n              onDragEnd={actions.onDragEndEntry}\n              onClick={(e) => {\n                e.stopPropagation();\n                manager.setActivePane(pane.paneId);\n                if (e.shiftKey || e.metaKey || e.ctrlKey) pane.toggleSelect(entry.path);\n                else if (entry.kind === "directory") pane.navigateTo(entry.path);\n                else pane.setSelection([entry.path]);\n              }}\n              onContextMenu={(e) => {\n                e.preventDefault();\n                e.stopPropagation();\n                if (!selectedSet.has(entry.path)) pane.setSelection([entry.path]);\n                actions.onOpenContext(entry, e.clientX, e.clientY);\n              }}\n            >\n              <TileIcon entry={entry} size={15} />\n              {renaming ? (\n                <InlineRenameInput\n                  initialName={entry.name}\n                  busy={pane.busy}\n                  onCommit={(name) => void pane.renameEntry(entry.path, name)}\n                  onCancel={() => pane.setRenamingPath(null)}\n                />\n              ) : (\n                <span className="miller-row-name">{entry.name}</span>\n              )}\n              {entry.kind === "directory" && (\n                <ChevronRight size={12} aria-hidden="true" className="miller-row-chevron" />\n              )}\n              <EntryActionButtons entry={entry} pane={pane} actions={actions} />\n            </div>\n          );\n        })}\n        {range.paddingAfter > 0 ? (\n          <div className="virtual-block-spacer" style={{ height: range.paddingAfter }} aria-hidden="true" />\n        ) : null}\n        {listing.hasNextPage ? (\n          <button\n            type="button"\n            className="miller-load-more"\n            disabled={listing.isFetchingNextPage}\n            onClick={() => void listing.fetchNextPage()}\n          >\n            {listing.isFetchingNextPage ? "加载中…" : "加载更多"}\n          </button>\n        ) : null}\n      </div>\n    </div>\n  );\n}\n\nexport function MillerColumns({\n  pane, homePath, actions, dropTarget,\n}: {\n  pane: UseFilePaneResult;\n  homePath: string;\n  actions: PaneActions;\n  dropTarget: string | null;\n}) {\n  const filesManager = useFilesManager();\n  const [container, setContainer] = useState<HTMLDivElement | null>(null);\n  const dirs = useMemo(() => columnDirsFor(pane.cwd, homePath), [pane.cwd, homePath]);\n  const chainKey = dirs.join("\\u0000");\n  useEffect(() => {\n    if (container) container.scrollLeft = container.scrollWidth;\n  }, [chainKey, container]);\n\n  const handleMarquee = useCallback((paths: string[], additive: boolean) => {\n    filesManager.setActivePane(pane.paneId);\n    pane.setSelection(additive\n      ? Array.from(new Set([...pane.selected, ...paths]))\n      : paths);\n  }, [filesManager, pane]);\n  const marquee = useMarqueeSelection({\n    itemSelector: '.miller-column[data-last-column="true"] .miller-row[data-path]',\n    blockedStartSelector: ".miller-row",\n    onSelect: handleMarquee,\n  });\n\n  return (\n    <div\n      className="miller-columns"\n      ref={setContainer}\n      onPointerDownCapture={marquee.onPointerDownCapture}\n      onPointerMoveCapture={marquee.onPointerMoveCapture}\n      onPointerUpCapture={marquee.onPointerUpCapture}\n      onPointerCancelCapture={marquee.onPointerCancelCapture}\n    >\n      {dirs.map((dir, idx) => (\n        <MillerColumn\n          key={dir}\n          user={filesManager.user}\n          dir={dir}\n          nextDir={idx + 1 < dirs.length ? (dirs[idx + 1] ?? null) : null}\n          isLast={idx === dirs.length - 1}\n          pane={pane}\n          actions={actions}\n          manager={filesManager}\n          dropTarget={dropTarget}\n        />\n      ))}\n      {marquee.marqueeStyle ? <div className="file-marquee" style={marquee.marqueeStyle} /> : null}\n    </div>\n  );\n}\n''',
)

# ---------------------------------------------------------------------------
# FilePane: use extracted virtual list and durable DataTransfer fallback.
# ---------------------------------------------------------------------------
file_pane_path = "apps/web/src/files/FilePane.tsx"
file_pane = read(file_pane_path)
file_pane = file_pane.replace('import Selecto from "react-selecto";\n', "", 1)
file_pane = file_pane.replace(
    'import { FileGrid } from "./FileGrid";\n',
    'import { FileGrid } from "./FileGrid";\nimport { FileListView } from "./FileListView";\n',
    1,
)
start = file_pane.index("function FileListView({")
end = file_pane.index("\nexport function FilePane", start)
file_pane = file_pane[:start] + file_pane[end + 1 :]
marker = 'import { useFilePane } from "./useFilePane";\n\n'
helper = '''import { useFilePane } from "./useFilePane";\n\nconst INTERNAL_FILE_DRAG_MIME = "application/x-107pilot-files";\n\nfunction dataTransferPayload(dataTransfer: DataTransfer): {\n  sourcePaneId: string;\n  entries: FileEntry[];\n} | null {\n  const raw = dataTransfer.getData(INTERNAL_FILE_DRAG_MIME);\n  if (!raw) return null;\n  try {\n    const decoded: unknown = JSON.parse(raw);\n    if (!decoded || typeof decoded !== "object") return null;\n    const value = decoded as { sourcePaneId?: unknown; entries?: unknown };\n    if (typeof value.sourcePaneId !== "string" || !Array.isArray(value.entries)) return null;\n    const entries = value.entries.filter((entry): entry is FileEntry => {\n      if (!entry || typeof entry !== "object") return false;\n      const item = entry as { path?: unknown; name?: unknown; kind?: unknown };\n      return typeof item.path === "string"\n        && typeof item.name === "string"\n        && typeof item.kind === "string";\n    });\n    return entries.length > 0 ? { sourcePaneId: value.sourcePaneId, entries } : null;\n  } catch {\n    return null;\n  }\n}\n\n'''
if marker not in file_pane:
    raise RuntimeError("FilePane import marker changed")
file_pane = file_pane.replace(marker, helper, 1)
old_drag = '''      manager.setDragPayload({ sourcePaneId: paneId, entries });\n      e.dataTransfer.effectAllowed = "move";\n      e.dataTransfer.setData("text/plain", paths.join("\\n"));\n'''
new_drag = '''      const payload = { sourcePaneId: paneId, entries };\n      manager.setDragPayload(payload);\n      e.dataTransfer.effectAllowed = "move";\n      e.dataTransfer.setData("text/plain", paths.join("\\n"));\n      e.dataTransfer.setData(INTERNAL_FILE_DRAG_MIME, JSON.stringify(payload));\n'''
if file_pane.count(old_drag) != 1:
    raise RuntimeError("FilePane drag start shape changed")
file_pane = file_pane.replace(old_drag, new_drag, 1)
old_drop = '''      const payload = manager.getDragPayload();\n      manager.setDragPayload(null);\n      if (!dest || !payload || payload.entries.length === 0) return;\n'''
new_drop = '''      const payload = manager.getDragPayload() ?? dataTransferPayload(e.dataTransfer);\n      manager.setDragPayload(null);\n      if (!dest || !payload || payload.entries.length === 0) return;\n'''
if file_pane.count(old_drop) != 1:
    raise RuntimeError("FilePane drop shape changed")
file_pane = file_pane.replace(old_drop, new_drop, 1)
write(file_pane_path, file_pane)

# ---------------------------------------------------------------------------
# CSS: fixed item geometry + overlay. Existing visual tokens preserved.
