styles_path = "apps/web/src/styles.css"
styles = read(styles_path)
css_marker = "/* UX-3 bounded file virtualization */"
if css_marker not in styles:
    styles += '''\n\n/* UX-3 bounded file virtualization */\n.virtual-spacer td {\n  padding: 0 !important;\n  border: 0 !important;\n  pointer-events: none;\n}\n.virtual-block-spacer { flex: none; pointer-events: none; }\n.files-table .file-row { height: 40px; }\n.file-tile {\n  height: 108px;\n  min-height: 108px;\n  box-sizing: border-box;\n}\n.miller-row {\n  height: 32px;\n  min-height: 32px;\n  box-sizing: border-box;\n}\n.file-marquee {\n  position: fixed;\n  z-index: 1400;\n  pointer-events: none;\n  border: 1px solid var(--teal);\n  background: color-mix(in srgb, var(--teal) 10%, transparent);\n  border-radius: 3px;\n}\n.virtual-filegrid-tiles { box-sizing: border-box; }\n'''
write(styles_path, styles)

# ---------------------------------------------------------------------------
# Browser fixture: real cursor pagination + bounded DOM regression.
